class Ticket:
    def __init__(self, code):
        self.code = code
    def label(self):
        return "BUG-" + self.code
t = Ticket("42")
print(t.label())

class Cart:
    def __init__(self):
        self.total = 0
    def add(self, x):
        self.total += x
a = Cart()
b = Cart()
a.add(5)
print(a.total, b.total)

